command:
const showGenericCard = game.pirateborg.api.showGenericCard;
const rollOutcome = game.pirateborg.api.outcomes.rollOutcome;
const MEAT = "Exquisite smoked meat";

// Buccan Cook lets you make d4 more rations from any edible animal you kill. The
// system can't know when you've made a kill, so this is a button you press then.
const outcome = await rollOutcome({ formula: "1d4", formulaLabel: "1d4 rations", data: actor.getRollData() })();
const made = Math.max(1, outcome.roll.total);

const existing = actor.items.find((i) => i.name === MEAT);
if (existing) {
  await existing.update({ "system.quantity": (existing.system.quantity || 0) + made });
} else {
  const meat = await game.pirateborg.api.compendium.findCompendiumItem("pirateborg.class-buccaneer", MEAT);
  if (!meat) {
    ui.notifications?.warn?.(`Could not find "${MEAT}" in the compendium.`);
    return;
  }
  const data = meat.toObject(false);
  data.system.quantity = made;
  await actor.createEmbeddedDocuments("Item", [data]);
}

outcome.title = `+${made} ration${made === 1 ? "" : "s"}`;
await showGenericCard({
  actor,
  title: "Cook rations",
  description: `You butcher and smoke your kill, making ${made} ration${made === 1 ? "" : "s"} of ${MEAT}.`,
  outcomes: [outcome],
});
